sql.if:

AND EXISTS (SELECT 1
              FROM T_CORE_ROLE_PERMISSION P
             WHERE P.PERMISSIONTYPEID = #{service_table}
               AND P.ROLEID = #{role_assigned}
               AND P.TARGETID = CONVERT(VARCHAR,T.ID))


AND NOT EXISTS (SELECT 1
                  FROM T_CORE_ROLE_PERMISSION P
                 WHERE P.PERMISSIONTYPEID = #{service_table}
                   AND P.ROLEID = #{role_unassigned}
                   AND P.TARGETID = CONVERT(VARCHAR,T.ID))


AND EXISTS (SELECT 1
              FROM T_CORE_USER_PERMISSION P
             WHERE P.PERMISSIONTYPEID = #{permissionTypeId}
               AND P.USERID = #{user_assigned}
               AND P.TARGETID = CONVERT(VARCHAR,T.ID))


AND NOT EXISTS (SELECT 1
                  FROM T_CORE_USER_PERMISSION P
                 WHERE P.PERMISSIONTYPEID = #{permissionTypeId}
                   AND P.USERID = #{user_unassigned}
                   AND P.TARGETID = CONVERT(VARCHAR,T.ID))

choose.when:

AND EXISTS (SELECT 1
              FROM ${targetFilter.targetTable.toUpperCase} F
             WHERE F.${targetFilter.targetMatchColumn.toUpperCase} = T.${targetFilter.thisMatchColumn.toUpperCase}


        AND F.${name.toUpperCase} = #{value}

)

choose.otherwise:

AND NOT EXISTS (SELECT 1
                  FROM ${targetFilter.targetTable.toUpperCase} F
                 WHERE F.${targetFilter.targetMatchColumn.toUpperCase} = T.${targetFilter.thisMatchColumn.toUpperCase}


        AND F.${name.toUpperCase} = #{value}

)

sql.if:
AND (


        ${advancedFilter.groupLink}



        ${advancedFilter.ingroupLink}



        (






                    "${advancedFilter.name.toUpperCase}" LIKE '${@com.sunwayworld.framework.database.sql.SqlHelper@getEscapedStrValue(advancedFilter.value)}%' ESCAPE '\'


                    "${advancedFilter.name.toUpperCase}" LIKE (#{advancedFilter.value} + '%')






                    "${advancedFilter.name.toUpperCase}" LIKE '%${@com.sunwayworld.framework.database.sql.SqlHelper@getEscapedStrValue(advancedFilter.value)}%' ESCAPE '\'


                    "${advancedFilter.name.toUpperCase}" LIKE ('%' + #{advancedFilter.value} + '%')






                    ("${advancedFilter.name.toUpperCase}" NOT LIKE '%${@com.sunwayworld.framework.database.sql.SqlHelper@getEscapedStrValue(advancedFilter.value)}%' ESCAPE '\' OR "${advancedFilter.name.toUpperCase}" IS NULL)


                    ("${advancedFilter.name.toUpperCase}" NOT LIKE ('%' + #{advancedFilter.value} + '%') OR "${advancedFilter.name.toUpperCase}" IS NULL)






                    "${advancedFilter.name.toUpperCase}" LIKE '%${@com.sunwayworld.framework.database.sql.SqlHelper@getEscapedStrValue(advancedFilter.value)}' ESCAPE '\'


                    "${advancedFilter.name.toUpperCase}" LIKE ('%' + #{advancedFilter.value})




            "${advancedFilter.name.toUpperCase}" = #{advancedFilter.value}


            "${advancedFilter.name.toUpperCase}" = #{advancedFilter.value}




                    UPPER("${advancedFilter.name.toUpperCase}") LIKE '${@com.sunwayworld.framework.database.sql.SqlHelper@getEscapedStrValue(advancedFilter.value)}%' ESCAPE '\'


                    UPPER("${advancedFilter.name.toUpperCase}") LIKE (#{advancedFilter.value} + '%')






                    UPPER("${advancedFilter.name.toUpperCase}") LIKE '%${@com.sunwayworld.framework.database.sql.SqlHelper@getEscapedStrValue(advancedFilter.value)}%' ESCAPE '\'


                    UPPER("${advancedFilter.name.toUpperCase}") LIKE ('%' + #{advancedFilter.value} + '%')






                    UPPER("${advancedFilter.name.toUpperCase}") LIKE '%${@com.sunwayworld.framework.database.sql.SqlHelper@getEscapedStrValue(advancedFilter.value)}' ESCAPE '\'


                    UPPER("${advancedFilter.name.toUpperCase}") LIKE ('%' + #{advancedFilter.value})




            UPPER("${advancedFilter.name.toUpperCase}") = #{advancedFilter.value}


            "${advancedFilter.name.toUpperCase}" > #{advancedFilter.value}


            "${advancedFilter.name.toUpperCase}" >= #{advancedFilter.value}


            "${advancedFilter.name.toUpperCase}" < #{advancedFilter.value}


            "${advancedFilter.name.toUpperCase}" <= #{advancedFilter.value}




                    "${advancedFilter.name.toUpperCase}" IS NULL


                    CONVERT(VARCHAR(10), "${advancedFilter.name.toUpperCase}", 20) = #{advancedFilter.value}




            "${advancedFilter.name.toUpperCase}" > #{advancedFilter.value}


            "${advancedFilter.name.toUpperCase}" >= #{advancedFilter.value}


            "${advancedFilter.name.toUpperCase}" < #{advancedFilter.value}


            "${advancedFilter.name.toUpperCase}" <= #{advancedFilter.value}




                    "${advancedFilter.name.toUpperCase}" IS NULL


                    CONVERT(VARCHAR(16), "${advancedFilter.name.toUpperCase}", 20) = #{advancedFilter.value}




            "${advancedFilter.name.toUpperCase}" > #{advancedFilter.value}


            "${advancedFilter.name.toUpperCase}" >= #{advancedFilter.value}


            "${advancedFilter.name.toUpperCase}" < #{advancedFilter.value}


            "${advancedFilter.name.toUpperCase}" <= #{advancedFilter.value}


            "${advancedFilter.name.toUpperCase}" = #{advancedFilter.value}




                    "${advancedFilter.name.toUpperCase}" IS NOT NULL


                    "${advancedFilter.name.toUpperCase}" <> #{advancedFilter.value}




    )

)

mapper.sql:
(SELECT K.TASKNAME + ',' FROM T_CORE_BPMN_INST I, T_CORE_BPMN_INST_TASK K WHERE I.ID = K.INSTID AND I.TARGETID = (#{service_table} + '$' + CONVERT (VARCHAR, T.ID))
AND K.STATUSCODE = #{bpmn_statusCode}
FOR XML PATH('')) TASKNAME_
